},{"ISHAPE":1}],["Très lent",{"T4":3},{"ISHAPE":2}]]},{"phase":"analyse","type":"radio","t":"Rétention d''eau","o":[["Basse",{},{}],["Moyenne",{"T3":1},{"PRESSO":1}],["Élevée",{"T2":1,"T3":2},{"PRESSO":2}]]},{"phase":"analyse","type":"radio","t":"Score InBody / 100","score":true,"o":[["Moins de 40",{},{}],["40 à 50",{},{}],["50 à 70",{},{}],["70 à 100",{},{}]]}],"AX":{"P1":{"name":"Réconfort","sig":"« l''aliment refuge »","feel":"Chez vous, l''aliment n''est pas un besoin, c''est une <b>régulation émotionnelle</b>. Face au stress, le cerveau réclame du sucre pour libérer de la dopamine, et le réconfort devient un réflexe.","imp":["Grignotage sucré du soir","Humeur en dents de scie","Culpabilité après les repas"],"note":"L''aliment sert d''apaisement émotionnel."},"P2":{"name":"Sous Pression","sig":"« le corps en alerte »","feel":"Votre corps vit en <b>état d''alerte permanent</b>. Le stress maintient un cortisol élevé, qui pousse à stocker sur le ventre et sabote le sommeil.","imp":["Stockage du ventre","Sommeil léger","Fringales de fin de journée"],"note":"Le stress entretient le stockage."},"P3":{"name":"Rupture","sig":"« le lien distendu »","feel":"Le lien avec votre image s''est <b>distendu</b>. À force de vous éviter dans le miroir, la motivation s''érode.","imp":["Évitement des miroirs","Baisse de confiance","Motivation en pointillés"],"note":"Le rapport à l''image s''est distendu."},"P4":{"name":"En Veille","sig":"« le corps endormi »","feel":"Votre corps tourne au ralenti. Moins de mouvement, c''est moins de masse musculaire, donc un <b>métabolisme qui s''endort</b>.","imp":["Fatigue au réveil","Masse musculaire en baisse","Le mouvement coûte"],"note":"Le corps est en veille, énergie basse."},"P5":{"name":"Résistance","sig":"« le corps verrouillé »","feel":"Votre corps s''est <b>verrouillé pour se protéger</b>. À force de régimes, le métabolisme s''est adapté à la baisse.","imp":["Effet yo-yo installé","Perte qui stagne","Découragement"],"note":"Métabolisme sur la défensive."},"T1":{"name":"Hormonal","sig":"« le stockage hormonal »","feel":"Vos hormones pilotent le stockage. Un déséquilibre discret suffit à <b>bloquer la perte</b> et orienter le stockage sur le ventre et les hanches.","imp":["Stockage ventre et hanches","Fatigue cyclique","Résistance à la perte"],"note":"Les hormones orientent le stockage."},"T2":{"name":"Inflammatoire","sig":"« le corps qui se défend »","feel":"Votre organisme entretient une <b>inflammation silencieuse</b>. Vos cellules stockent par réflexe de protection et retiennent l''eau.","imp":["Rétention d''eau","Ventre gonflé le matin","Peau réactive"],"note":"Une inflammation de fond fait retenir."},"T3":{"name":"Circulatoire","sig":"« les fluides qui stagnent »","feel":"Votre circulation est paresseuse. Les <b>fluides stagnent</b> et s''accumulent dans le bas du corps.","imp":["Jambes lourdes","Gonflement du bas du corps","Cellulite aqueuse"],"note":"Les fluides stagnent en bas du corps."},"T4":{"name":"Métabolique Lent","sig":"« le moteur au ralenti »","feel":"Votre moteur brûle au ralenti. Vous dépensez moins que vous ne stockez, avec une <b>signature thyroïdienne discrète</b>.","imp":["Perte de poids lente","Frilosité","Coup de barre après les repas"],"note":"Le métabolisme brûle lentement."},"T5":{"name":"Digestif","sig":"« l''assimilation ralentie »","feel":"Votre digestion peine à suivre. <b>Assimilation et élimination sont ralenties</b>, le ventre gonfle.","imp":["Ballonnements","Transit irrégulier","Lourdeur après manger"],"note":"Digestion et élimination ralenties."}},"CAT":{"elig":["Santé & éligibilité","#DCE9F5","#3E6289"],"alim":["Alimentation","#E2E6F3","#4A5788"],"emo":["Émotions & stress","#E8E4F1","#5D4F86"],"image":["Estime & image","#EEE4EF","#71527D"],"energie":["Énergie & activité","#F3E4EA","#855370"],"corps":["Signaux du corps","#F7E3E7","#954F64"],"histo":["Historique & objectif","#FBE3EA","#A24E6C"]},"PRESTA":{"LUXO":{"n":"Luxothérapie Perte de poids","d":"Relance l''